select fixture_assert((select not prosecdef from pg_proc where oid='public.rename_household(uuid,text,text)'::regprocedure),'public wrapper is invoker');
select fixture_assert((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='private.rename_household(uuid,text,text)'::regprocedure),'private definer fixed empty search_path');
select fixture_assert(not has_function_privilege('anon','public.rename_household(uuid,text,text)','execute') and not has_function_privilege('anon','private.rename_household(uuid,text,text)','execute'),'anon cannot execute either endpoint');
select fixture_assert(has_function_privilege('authenticated','public.rename_household(uuid,text,text)','execute') and has_function_privilege('authenticated','private.rename_household(uuid,text,text)','execute'),'authenticated can reach guarded endpoint');
set role authenticated;
select set_config('request.jwt.claim.sub','','false');
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000001','A','Personal')$q$,'Sign in');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000013',false);
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002','A','Shared')$q$,'Only household owners or managers');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000014',false);
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002','A','Shared')$q$,'Only household owners or managers');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000099',false);
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002','A','Shared')$q$,'Only household owners or managers');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000011',false);
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000003','A','Other')$q$,'Only household owners or managers');
select fixture_assert(public.rename_household('00000000-0000-4000-8000-000000000001','  Collins'||chr(160)||chr(8194)||'Home  ','Personal')->>'name'='Collins Home','owner renames own personal household with normalized Unicode whitespace');
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002',' ','Shared')$q$,'Enter a household name');
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002',null,'Shared')$q$,'Enter a household name');
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002',repeat('x',81),'Shared')$q$,'80 characters');
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002','a'||chr(1),'Shared')$q$,'letters, numbers');
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002','a'||chr(159),'Shared')$q$,'letters, numbers');
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002','A',null)$q$,'household_name_conflict');
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002','A','Outdated')$q$,'household_name_conflict');
select fixture_assert(public.rename_household('00000000-0000-4000-8000-000000000002',repeat('🏡',80),'Shared')->>'name'=repeat('🏡',80),'80 Unicode codepoints accepted');
select fixture_error($q$select public.rename_household('00000000-0000-4000-8000-000000000002',repeat('🏡',81),repeat('🏡',80))$q$,'80 characters');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000012',false);
select fixture_assert(public.rename_household('00000000-0000-4000-8000-000000000002','Cousin''s home & 🏡',repeat('🏡',80))->>'name'='Cousin''s home & 🏡','manager can rename shared household with apostrophe and emoji');
select fixture_assert(public.rename_household('00000000-0000-4000-8000-000000000002','Cousin''s home & 🏡',repeat('🏡',80))->>'name'='Cousin''s home & 🏡','same desired name is idempotent after lost ACK');
do $$ declare changed integer; begin update public.households set name='Raw bypass' where id='00000000-0000-4000-8000-000000000002'; get diagnostics changed = row_count; perform fixture_assert(changed=0,'direct UPDATE still denied by existing RLS'); end $$;
reset role;
select fixture_assert((select jsonb_agg(to_jsonb(h)-'name' order by id) from public.households h)=(select households from fixture_before),'all household identity metadata unchanged');
select fixture_assert((select jsonb_agg(to_jsonb(m) order by household_id,user_id) from public.household_members m)=(select members from fixture_before),'memberships unchanged');
select fixture_assert((select jsonb_agg(to_jsonb(f)) from public.financial_fixture f)=(select finances from fixture_before),'financial rows unchanged');
select fixture_assert((select jsonb_agg(to_jsonb(p)) from pg_policy p where polrelid='public.households'::regclass)=(select policies from fixture_before),'existing household RLS unchanged');
select 'HOUSEHOLD NAME TESTS COMPLETE';
